public class MaquinaAlgodon extends Maquina {
    protected int potencia;

    public MaquinaAlgodon() {
        super();
        potencia = 0;
    }

    public MaquinaAlgodon(String codigo, String marca, String modelo, float tarifa, int potencia) {
        super(codigo, marca, modelo, tarifa);
        this.potencia = potencia;
    }

    public void setPotencia(int newPotencia) {
        potencia = newPotencia;
    }

    public int getPotencia() {
        return potencia;
    }

    @Override
    public float Cotizacion(int dias) {
        float total = tarifa * dias;
        if (potencia > 1000) {
            total += 60;
        }

        return total;
    }

    @Override
    public String getTipo() {
        return "Algodon";
    }

	@Override
	public void mostrarCaracteristicas() {
    	System.out.println("Potencia: " + potencia + " W");
	}
}